cd /tmp/mgwork && cat > brief.py <<'EOF'
import pickletools, sys
INTEREST = {"GLOBAL","STACK_GLOBAL","REDUCE","BUILD","INST","OBJ","NEWOBJ","NEWOBJ_EX","STOP","PROTO","PERSID","BINPERSID","EXT1","EXT2","EXT4","GET","BINGET","LONG_BINGET","PUT","BINPUT","LONG_BINPUT","MEMOIZE"}
def brief(data, base=0):
    pos = 0; n = 0
    while pos < len(data):
        ops = []
        try:
            for t in pickletools.genops(data[pos:]):
                ops.append(t)
        except Exception as e:
            print(f"  ERR stream {n} @ {base+pos}: {e} (parsed {len(ops)} ops)")
            if not ops: break
        window = []
        for i,(op,arg,p) in enumerate(ops):
            if op.name in INTEREST and op.name not in ("BINPUT","MEMOIZE","PUT","LONG_BINPUT","BINGET","GET","LONG_BINGET"):
                ctx = []
                if op.name in ("STACK_GLOBAL","REDUCE","BUILD","OBJ","NEWOBJ","INST"):
                    for (o2,a2,p2) in ops[max(0,i-4):i]:
                        if o2.name in ("BINPUT","MEMOIZE","PUT","LONG_BINPUT","FRAME"): continue
                        ctx.append(f"{o2.name}:{repr(a2)[:50]}")
                print(f"  [{n}] {base+pos+p:6d} {op.name:12s} {repr(arg)[:70]:30s} <- {' | '.join(ctx)}")
        if not ops: break
        last = ops[-1]
        if last[0].name != "STOP": break
        pos += last[2] + 1; n += 1
    print(f"  end {base+pos}/{len(data)} trailing={data[pos:pos+40]!r}")
if __name__ == "__main__":
    brief(open(sys.argv[1],'rb').read())
EOF
