                r = hit[0] if hit else None
                if r and (r.startswith("cm:") or r.startswith("sm:")):
                    r = "o:" + r[3:]
            else:
                r = None
            if not r or r == "v":
                ok = False
                break
            cur_ref = r
        if ok and cur_ref.startswith("o:"):
            return cur_ref[2:]
        if ok and cur_ref.startswith("m:"):
            return cur_ref
        return None
    return None

