                gi = self.classobj_raw(cls, "__getitem__")
                if gi is not NOTFOUND:
                    return self.call(gi, (obj, key), {}, "__getitem__")
            store = obj.extra.get("items")
            if store is not None and is_hashable(key) and key in store:
                return store[key]
