    if isinstance(v, (str, bytes)):
        return True
    if isinstance(v, Instance) and isinstance(v.cls, Ref) and v.cls.oid.startswith("pathlib."):
        return True
    if isinstance(v, int) and not isinstance(v, bool):
        return True
    return False


