    (0x8D, "op_binunicode8"), (0x8E, "op_binbytes8"), (0x8F, "op_empty_set"), (0x90, "op_additems"),
    (0x91, "op_frozenset"), (0x92, "op_newobj_ex"), (0x93, "op_stack_global"), (0x94, "op_memoize"),
