                    mdict = dict(members)
                    if not first or "/" not in first:
                        raise SimError("file in archive is not in a subdirectory")
                    prefix = first.split("/", 1)[0]
                    if f"{prefix}/data.pkl" not in mdict:
                        raise SimError("archive has no data.pkl")
