            ctx.loc = saved_loc


def _strip_ext(name, exts):
    low = name.lower()
    for e in exts:
        if low.endswith(e):
            base = name[: len(name) - len(e)]
            return base + ".tar" if e in (".tgz", ".tbz2", ".tbz", ".txz") else base
    return name

