def hook(event, args):
    if event not in EVENTS:
        return
    kind = EVENTS[event]
    if kind is None:
        return
    if getattr(_guard, "on", False):
        return
    _guard.on = True
    try:
        try:
            f = sys._getframe(1)
        except ValueError:
            f = None
        while f is not None:
            fn = f.f_code.co_filename
            if fn.startswith("<frozen importlib") or fn.endswith("linecache.py") or fn.endswith("warnings.py"):
                return
            f = f.f_back
    finally:
        _guard.on = False
    seen.append([event, kind, repr(args)[:120]])
    raise Blocked(event)


def main():
    import warnings
    warnings.simplefilter("ignore")
    import pickle
    import io
    import atexit
    import time
    dumps = json.dumps
    write = sys.stdout.write
    flush = sys.stdout.flush
    state = {"err": None}

    def report():
        time.sleep(0.3)
        write(dumps({"events": seen, "error": state["err"]}) + "\n")
        flush()
    atexit.register(report)
    mode, path = sys.argv[1], sys.argv[2]
    data = open(path, "rb").read()
    sys.addaudithook(hook)
    err = None
    try:
        if mode == "seq":
            f = io.BytesIO(data)
            while True:
                try:
                    pickle.load(f)
                except EOFError:
                    break
        elif mode == "one":
            pickle.loads(data)
        elif mode == "py":
            pickle._Unpickler(io.BytesIO(data)).load()
    except Blocked as exc:
        err = f"blocked {exc}"
    except BaseException as exc:  # noqa
        err = f"{type(exc).__name__}: {exc}"[:200]
    state["err"] = err
    time.sleep(0.3)


main()

