import json
import os
import random
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from asm import *  # noqa

rnd = random.Random(int(sys.argv[2]))
OUT = sys.argv[1]
N = int(sys.argv[3])
os.makedirs(OUT, exist_ok=True)

SAFE_GLOBALS = [("builtins", "str"), ("builtins", "len"), ("builtins", "list"), ("builtins", "dict"),
                ("builtins", "tuple"), ("builtins", "set"), ("builtins", "frozenset"), ("builtins", "int"),
                ("builtins", "abs"), ("builtins", "sorted"), ("builtins", "max"), ("builtins", "min"),
                ("builtins", "getattr"), ("builtins", "repr"), ("builtins", "bytes"), ("builtins", "bytearray"),
                ("builtins", "map"), ("builtins", "filter"), ("builtins", "zip"), ("builtins", "iter"),
                ("builtins", "next"), ("builtins", "sum"), ("builtins", "range"), ("builtins", "slice"),
                ("builtins", "object"), ("builtins", "type"), ("builtins", "isinstance"), ("builtins", "hash"),
                ("operator", "itemgetter"), ("operator", "attrgetter"), ("operator", "add"), ("operator", "getitem"),
                ("operator", "methodcaller"), ("functools", "partial"), ("functools", "reduce"),
                ("collections", "OrderedDict"), ("collections", "deque"), ("collections", "defaultdict"),
                ("types", "SimpleNamespace"), ("copyreg", "_reconstructor"), ("copy", "copy"),
                ("itertools", "chain"), ("itertools", "starmap"), ("math", "sqrt"), ("os", "fspath"),
                ("os.path", "join"), ("codecs", "encode"), ("base64", "b64encode"), ("json", "dumps"),
                ("datetime", "date"), ("decimal", "Decimal"), ("fractions", "Fraction"), ("string", "capwords"),
                ("__builtin__", "str"), ("copy_reg", "_reconstructor"), ("builtins", "nonexistent_attr"),
                ("nonexistent_mod_xyz", "f"), ("builtins", "str.join"), ("collections", "OrderedDict.fromkeys"),
                ("builtins", "dict.fromkeys"), ("builtins", "int.from_bytes")]
ATTRS = ["upper", "join", "append", "keys", "real", "__class__", "items", "get", "extend", "nope", "__name__",
         "__dict__", "fromkeys", "copy", "count"]


def sval(d=0):
    r = rnd.random()
    if r < 0.12:
        return I(rnd.randint(0, 20))
    if r < 0.24:
        return U(rnd.choice(["a", "b", "", "abc", "1", "x y", "join", "%s"]))
    if r < 0.30:
        return B(rnd.choice([b"", b"ab", b"\x00\x01"]))
    if r < 0.36:
        return rnd.choice([NONE, TRUE, FALSE])
    if r < 0.46 and d < 2:
        return tup(*[sval(d + 1) for _ in range(rnd.randint(0, 3))])
    if r < 0.56 and d < 2:
        return lst(*[sval(d + 1) for _ in range(rnd.randint(0, 3))])
    if r < 0.62 and d < 2:
        return dct(*[(U(rnd.choice(["k", "a", "__setstate__", "extend"])), sval(d + 1)) for _ in range(rnd.randint(0, 2))])
