        return U(rnd.choice(ATTRS))
    if r < 0.86:
        m, n = rnd.choice(SAFE_GLOBALS)
        return (U(m) + U(n) + b"\x93") if rnd.random() < 0.5 else G(m, n)
    if d < 2:
        m, n = rnd.choice(SAFE_GLOBALS)
        return call(G(m, n), *[sval(d + 1) for _ in range(rnd.randint(0, 3))])
    return NONE


def body():
    out = b""
    for _ in range(rnd.randint(1, 5)):
        r = rnd.random()
        if r < 0.45:
            out += sval() + POP
        elif r < 0.6:
            out += sval() + sval() + BUILD + POP
        elif r < 0.68:
            out += sval() + MARK + sval() + sval() + APPENDS + POP
        elif r < 0.74:
            out += sval() + sval() + sval() + SETITEM + POP
        elif r < 0.8:
